mapper.insert:
INSERT INTO auth_security_event (
    id, user_id, session_id, event_type, risk_level, client_type, device_name,
    device_fingerprint_hash, event_scope_key, status, occurred_at, read_at
)
SELECT #{event.id}, #{event.userId}, #{event.sessionId,jdbcType=BIGINT},
       #{event.eventType}, #{event.riskLevel}, #{event.clientType}, #{event.deviceName},
       #{event.deviceFingerprintHash}, #{event.eventScopeKey}, #{event.status},
       #{event.occurredAt}, #{event.readAt,jdbcType=TIMESTAMP}
WHERE NOT EXISTS (
    SELECT 1 FROM auth_security_event
    WHERE user_id = #{event.userId}
      AND event_type = #{event.eventType}
      AND event_scope_key = #{event.eventScopeKey}
)

